baf2ef84f Also clear groups with no members when clearing database
9eecdb6ed eng-2438-stop-users-from-joining-another-users-space-access-through-a
 packages/database/features/groupMembership.feature | 39 +++++++++++
 .../database/features/step-definitions/stepdefs.ts | 80 +++++++++++++++++++++-
 packages/database/src/dbTypes.ts                   |  1 -
 ...29130000_group_membership_insert_admin_only.sql |  6 ++
 packages/database/supabase/schemas/account.sql     | 11 +--
 5 files changed, 124 insertions(+), 13 deletions(-)
diff --git a/packages/database/features/groupMembership.feature b/packages/database/features/groupMembership.feature
new file mode 100644
index 000000000..58fa80642
--- /dev/null
+++ b/packages/database/features/groupMembership.feature
@@ -0,0 +1,39 @@
+Feature: Group membership
+  User story:
+  * As a user of a plugin
+  * Logged in through a given space's anonymous account
+  * I can share my space with a group
+  * But nobody can join a group without an admin's consent
+
+  Acceptance criteria:
+  * A user cannot join another user's id as if it were a group
+  * Nobody can join a group after its last member leaves
+
+  Background:
+    Given the database is blank
+    And the user user1 opens the Roam plugin in space s1
+    And the user user2 opens the Roam plugin in space s2
+
+  Scenario: A reader of a space cannot join its editor as a group to gain editor access
+    When user of space s1 creates group my_group
+    And user of space s1 adds space s2 to group my_group
+    And SpaceAccess are added to the database:
+      | _account_uid | _space_id | permissions |
+      | my_group     | s1        | reader      |
+    Then user of space s2 fails to join an editor of space s1 as a group
+    And user user2 fails to upsert these documents to space s1:
+      """json
+      [
+        {
+          "source_local_id": "s1",
+          "created": "2000/01/01",
+          "last_modified": "2001/01/02",
+          "author_local_id": "user1"
+        }
+      ]
+      """
+
+  Scenario: Nobody can join a group after its last member leaves
+    When user of space s1 creates group my_group
+    And user of space s1 leaves group my_group
+    Then user of space s2 fails to add itself to group my_group
diff --git a/packages/database/features/step-definitions/stepdefs.ts b/packages/database/features/step-definitions/stepdefs.ts
index 90ef71f39..6b9b25668 100644
--- a/packages/database/features/step-definitions/stepdefs.ts
+++ b/packages/database/features/step-definitions/stepdefs.ts
@@ -69,10 +69,12 @@ Given("the database is blank", async () => {
   assert.equal(r.error, null);
   r = await client.from("AgentIdentifier").delete().neq("account_id", -1);
   assert.equal(r.error, null);
-  const r3 = await client.from("group_membership").select("group_id");
+  // Find groups by their flag, not their members: a group can be left without members.
+  const r3 = await client.auth.admin.listUsers({ perPage: 1000 });
   assert.equal(r3.error, null);
-  // eslint-disable-next-line @typescript-eslint/naming-convention
-  const groupIds = new Set((r3.data || []).map(({ group_id }) => group_id));
+  const groupIds = r3.data.users
+    .filter((user) => user.user_metadata?.group === true)
+    .map((user) => user.id);
   for (const id of groupIds) {
     const ur = await client.auth.admin.deleteUser(id);
     assert.equal(ur.error, null);
@@ -927,3 +929,75 @@ When(
     assert.equal(r2.error, null);
   },
 );
+
+When(
+  "user of space {word} leaves group {word}",
+  async (spaceName: string, groupName: string): Promise<void> => {
+    const localRefs = (world.localRefs || {}) as LocalRefsType;
+    const spaceId = localRefs[spaceName];
+    const groupId = localRefs[groupName];
+    if (typeof spaceId !== "number") assert.fail("spaceId not a number");
+    if (typeof groupId !== "string") assert.fail("groupId not a string");
+    const client = await getLoggedinDatabase(spaceId);
+    const memberId = (await client.auth.getUser()).data.user?.id;
+    assert.ok(memberId, "user of space not logged in");
+    const response = await client
+      .from("group_membership")
+      .delete()
+      .eq("group_id", groupId)
+      .eq("member_id", memberId)
+      .select();
+    assert.equal(response.error, null);
+    assert.equal(response.data?.length, 1);
+  },
+);
+
+const failToJoinGroup = async (
+  spaceId: number,
+  groupId: string,
+): Promise<void> => {
+  const client = await getLoggedinDatabase(spaceId);
+  const memberId = (await client.auth.getUser()).data.user?.id;
+  assert.ok(memberId, "user of space not logged in");
+  const response = await client
+    .from("group_membership")
+    .insert({ group_id: groupId, member_id: memberId });
+  assert.equal(response.error?.code, INSUFFICIENT_PRIVILEGE);
+};
+
+Then(
+  "user of space {word} fails to add itself to group {word}",
+  async (spaceName: string, groupName: string): Promise<void> => {
+    const localRefs = (world.localRefs || {}) as LocalRefsType;
+    const spaceId = localRefs[spaceName];
+    const groupId = localRefs[groupName];
+    if (typeof spaceId !== "number") assert.fail("spaceId not a number");
+    if (typeof groupId !== "string") assert.fail("groupId not a string");
+    await failToJoinGroup(spaceId, groupId);
+  },
+);
+
+// The joining user reads the editor's id through its own client,
+// as an attacker with reader access would.
+Then(
+  "user of space {word} fails to join an editor of space {word} as a group",
+  async (space1Name: string, space2Name: string): Promise<void> => {
+    const localRefs = (world.localRefs || {}) as LocalRefsType;
+    const space1Id = localRefs[space1Name];
+    const space2Id = localRefs[space2Name];
+    if (typeof space1Id !== "number") assert.fail("space1Id not a number");
+    if (typeof space2Id !== "number") assert.fail("space2Id not a number");
+    const client1 = await getLoggedinDatabase(space1Id);
+    const r1 = await client1
+      .from("SpaceAccess")
+      .select("account_uid")
+      .eq("space_id", space2Id)
+      .eq("permissions", "editor")
+      .limit(1)
+      .maybeSingle();
+    assert.equal(r1.error, null);
+    const editorId = r1.data?.account_uid;
+    assert.ok(editorId, `user of space ${space1Name} cannot see an editor`);
+    await failToJoinGroup(space1Id, editorId);
+  },
+);
