       in_space: {
         Args: {
diff --git a/packages/database/supabase/migrations/20261029130000_group_membership_insert_admin_only.sql b/packages/database/supabase/migrations/20261029130000_group_membership_insert_admin_only.sql
new file mode 100644
index 000000000..35c1a18e7
--- /dev/null
+++ b/packages/database/supabase/migrations/20261029130000_group_membership_insert_admin_only.sql
@@ -0,0 +1,6 @@
+-- NOT group_exists(group_id) let anyone join any user id that was not yet a group, including another user's, and so gain that user's space access.
+DROP POLICY IF EXISTS group_membership_insert_policy ON public.group_membership;
+CREATE POLICY group_membership_insert_policy ON public.group_membership FOR INSERT WITH CHECK (public.is_group_admin(group_id));
+COMMENT ON POLICY group_membership_insert_policy ON public.group_membership IS 'Only group admins add members. The create-group edge function adds the first admin with the service role, and accept_group_invitation adds invited members as a security definer.';
+-- Unused once the policy no longer calls it.
+DROP FUNCTION IF EXISTS public.group_exists(UUID);
diff --git a/packages/database/supabase/schemas/account.sql b/packages/database/supabase/schemas/account.sql
index 3171a316e..5335cd2ef 100644
--- a/packages/database/supabase/schemas/account.sql
+++ b/packages/database/supabase/schemas/account.sql
@@ -254,14 +254,6 @@ AS $$
         WHERE member_id = auth.uid() AND group_id = group_id_ AND admin);
 $$;

-CREATE OR REPLACE FUNCTION public.group_exists(group_id_ UUID) RETURNS BOOLEAN
-STABLE SECURITY DEFINER
-SET search_path = ''
-LANGUAGE sql
-AS $$
-    SELECT EXISTS (SELECT true FROM public.group_membership WHERE group_id = group_id_ LIMIT 1);
-$$;
-
 CREATE OR REPLACE FUNCTION public.my_space_ids(access_level public."SpaceAccessPermissions" = 'reader') RETURNS BIGINT []
 STABLE SECURITY DEFINER
 SET search_path = ''
@@ -589,7 +581,8 @@ DROP POLICY IF EXISTS group_membership_delete_policy ON public.group_membership;
 CREATE POLICY group_membership_delete_policy ON public.group_membership FOR DELETE USING (member_id = auth.uid() OR public.is_group_admin(group_id));

 DROP POLICY IF EXISTS group_membership_insert_policy ON public.group_membership;
-CREATE POLICY group_membership_insert_policy ON public.group_membership FOR INSERT WITH CHECK (public.is_group_admin(group_id) OR NOT public.group_exists(group_id));
+CREATE POLICY group_membership_insert_policy ON public.group_membership FOR INSERT WITH CHECK (public.is_group_admin(group_id));
+COMMENT ON POLICY group_membership_insert_policy ON public.group_membership IS 'Only group admins add members. The create-group edge function adds the first admin with the service role, and accept_group_invitation adds invited members as a security definer.';

 DROP POLICY IF EXISTS group_membership_update_policy ON public.group_membership;
 CREATE POLICY group_membership_update_policy ON public.group_membership FOR UPDATE USING (public.is_group_admin(group_id));

