---
// Follow this setup guide to integrate the Deno language server with your editor:
// https://deno.land/manual/getting_started/setup_your_environment
// This enables autocomplete, go to definition, etc.

import "@supabase/functions-js/edge-runtime";
import { corsHeaders } from "@supabase/supabase-js/cors";
import { createClient, type UserResponse } from "@supabase/supabase-js";
import type { DGSupabaseClient } from "@repo/database/lib/client";

// The following lines are duplicated from apps/website/app/utils/llm/cors.ts
const allowedOrigins = [
  "https://roamresearch.com",
  "http://localhost:3000",
  "app://obsidian.md",
];

const isVercelPreviewUrl = (origin: string): boolean =>
  /^https:\/\/.*-discourse-graph-[a-z0-9]+\.vercel\.app$/.test(origin);

const isAllowedOrigin = (origin: string): boolean =>
  allowedOrigins.some((allowed) => origin.startsWith(allowed)) ||
  isVercelPreviewUrl(origin);

// @ts-ignore Deno is not visible to the IDE
Deno.serve(async (req) => {
  const origin = req.headers.get("origin");
  const originIsAllowed = origin && isAllowedOrigin(origin);
  const myCorsHeaders = {
    ...corsHeaders,
    "Access-Control-Allow-Origin": originIsAllowed ? origin : "",
  };
  if (req.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: myCorsHeaders,
    });
  }
  if (req.method !== "POST") {
    return Response.json(
      { msg: "Method not allowed" },
      { status: 405, headers: myCorsHeaders },
    );
  }
  let input: { name?: string } = {};
  try {
    input = await req.json();
  } catch (error) {
    return Response.json(
      {
        msg: "Invalid JSON in request body",
        error: error instanceof Error ? error.message : String(error),
      },
      {
        status: 400,
        headers: myCorsHeaders,
      },
    );
  }
  const groupName = input.name;
  if (groupName === undefined) {
    return new Response("Missing group name", {
      status: 400,
      headers: myCorsHeaders,
    });
  }
  // @ts-ignore Deno is not visible to the IDE
  const url = Deno.env.get("SUPABASE_URL");
  let service_key: string | undefined;
  let anon_key: string | undefined;
  try {
    // @ts-ignore Deno is not visible to the IDE
    const secretKeysRaw = Deno.env.get("SUPABASE_SECRET_KEYS");
    // @ts-ignore Deno is not visible to the IDE
    const publishableKeysRaw = Deno.env.get("SUPABASE_PUBLISHABLE_KEYS");
    if (secretKeysRaw)
      service_key = JSON.parse(secretKeysRaw)["default"] as string;
    if (publishableKeysRaw)
      anon_key = JSON.parse(publishableKeysRaw)["default"] as string;
  } catch {
    // fall through to the guard below
  }

  if (!url || !anon_key || !service_key) {
    return new Response(
      "Missing SUPABASE_URL or SUPABASE_SECRET_KEYS or SUPABASE_PUBLISHABLE_KEYS",
      {
        status: 500,
        headers: myCorsHeaders,
      },
