  client: DGSupabaseClient;
  groupId: string;
  admin?: boolean;
}): Promise<string | null> => {
  const userData = await getSessionBaseUserData(client);
  if (!userData) return null;
  const membershipReq = await client
    .from("group_membership")
    .select("admin")
    .eq("group_id", groupId)
    .eq("member_id", userData.id)
